package com.procurement.rfq.specification; import com.procurement.rfq.entity.*; import org.springframework.data.jpa.domain.Specification; public final class RfqSpecification{private RfqSpecification(){}public static Specification<Rfq> search(String keyword,RfqStatus status,Long departmentId){return(r,q,b)->{var p=b.conjunction();if(keyword!=null&&!keyword.isBlank()){var k="%"+keyword.toLowerCase()+"%";p=b.and(p,b.like(b.lower(r.get("rfqNumber")),k));}if(status!=null)p=b.and(p,b.equal(r.get("status"),status));if(departmentId!=null)p=b.and(p,b.equal(r.get("purchaseRequest").get("department").get("id"),departmentId));return p;};}}
